package dk.foss.jarvis.data

import org.junit.Assert.*
import org.junit.Test

class DeviceRegistryMigrationTest {
    private class FakeCipher : AeadCipher { override fun encrypt(p: String) = "enc($p)"; override fun decrypt(b: String) = b.removePrefix("enc(").removeSuffix(")") }
    private class MemBlobs : SecretBlobStore { val map=mutableMapOf<String,String>(); override fun get(a:String)=map[a]; override fun put(a:String,b:String){map[a]=b}; override fun remove(a:String){map.remove(a)} }
    private fun legacy(s: SecureStore) { s.saveDeviceId("legacy-device"); s.savePushEndpoint("legacy-fcm-token") }
    @Test fun `legacy record with valid settings migrates in place`() { val s=SecureStore(FakeCipher(),MemBlobs()); legacy(s); val r=DeviceRegistryStore(s).loadOrMigrate(JarvisSettings("http://hermes-a:8642/","bearer-a")) as RegistryState.Registered; assertEquals("legacy-device",r.registration.deviceId); assertEquals("legacy-fcm-token",r.registration.pushEndpoint); assertEquals("http://hermes-a:8642",r.registration.hermesOrigin); assertEquals("bearer-a",r.registration.apiKey); assertEquals("http://hermes-a:8642",s.loadPushOrigin()); assertEquals("bearer-a",s.loadPushApiKey()) }
    @Test fun `migration keeps the same device id`() { val s=SecureStore(FakeCipher(),MemBlobs()); legacy(s); assertEquals("legacy-device",(DeviceRegistryStore(s).loadOrMigrate(JarvisSettings("http://a","k")) as RegistryState.Registered).registration.deviceId) }
    @Test fun `migration does not create a new device`() { val b=MemBlobs(); val s=SecureStore(FakeCipher(),b); legacy(s); val id=b.map[SecureStore.DEVICE_ID_ALIAS]; val ep=b.map[SecureStore.ENDPOINT_ALIAS]; assertTrue(DeviceRegistryStore(s).loadOrMigrate(JarvisSettings("http://a","k")) is RegistryState.Registered); assertEquals(id,b.map[SecureStore.DEVICE_ID_ALIAS]); assertEquals(ep,b.map[SecureStore.ENDPOINT_ALIAS]) }
    @Test fun `migration is idempotent and the first binding wins`() { val b=MemBlobs(); val s=SecureStore(FakeCipher(),b); legacy(s); val r=DeviceRegistryStore(s); r.loadOrMigrate(JarvisSettings("http://hermes-a:8642/","a")); val snap=b.map.toMap(); val x=r.loadOrMigrate(JarvisSettings("http://hermes-b:9999","b")) as RegistryState.Registered; assertEquals("http://hermes-a:8642",x.registration.hermesOrigin); assertEquals("a",x.registration.apiKey); assertEquals(snap,b.map) }
    @Test fun `legacy without bearer is not migrated`() { val s=SecureStore(FakeCipher(),MemBlobs()); legacy(s); assertTrue(DeviceRegistryStore(s).loadOrMigrate(JarvisSettings("http://a","")) is RegistryState.Empty); assertNull(s.loadPushOrigin()); assertNull(s.loadPushApiKey()) }
    @Test fun `legacy without base url is not migrated`() { val s=SecureStore(FakeCipher(),MemBlobs()); legacy(s); assertTrue(DeviceRegistryStore(s).loadOrMigrate(JarvisSettings("","k")) is RegistryState.Empty); assertNull(s.loadPushOrigin()); assertNull(s.loadPushApiKey()) }
    @Test fun `fully registered device is returned untouched`() { val b=MemBlobs(); val s=SecureStore(FakeCipher(),b); val r=DeviceRegistryStore(s); r.save("dev","tok","http://other:9","k9"); val snap=b.map.toMap(); val x=r.loadOrMigrate(JarvisSettings("http://a","a")) as RegistryState.Registered; assertEquals(DeviceRegistration("dev","tok","http://other:9","k9"),x.registration); assertEquals(snap,b.map) }
    @Test fun `partial registration backfills only the missing credential`() { val s=SecureStore(FakeCipher(),MemBlobs()); val r=DeviceRegistryStore(s); r.save("dev","tok","http://pinned:1",""); val x=r.loadOrMigrate(JarvisSettings("http://a","bearer-a")) as RegistryState.Registered; assertEquals("http://pinned:1",x.registration.hermesOrigin); assertEquals("bearer-a",x.registration.apiKey) }
    @Test fun `endpoint missing reads as empty registry`() { val s=SecureStore(FakeCipher(),MemBlobs()); s.saveDeviceId("dev"); assertEquals(RegistryState.Empty,DeviceRegistryStore(s).loadOrMigrate(JarvisSettings("http://a","k"))) }
}
